def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    walls = [c for c in components(g == 2)]
    markers = [(y, x, int(g[y, x])) for y in range(H) for x in range(W)
               if g[y, x] not in (0, 2, 4)]
    # greedy pairing walls <-> markers by Chebyshev distance
    pairs = []
    for wi, w in enumerate(walls):
        for mi, (my, mx, mc) in enumerate(markers):
            d = min(max(abs(my - y), abs(mx - x)) for y, x in w)
            pairs.append((d, wi, mi))
    pairs.sort()
    usedw, usedm, assign = set(), set(), {}
    for d, wi, mi in pairs:
        if wi in usedw or mi in usedm:
            continue
        usedw.add(wi); usedm.add(mi); assign[wi] = mi
    for (my, mx, mc) in markers:
        out[my, mx] = 0
    emit(out.copy(), "Remove the single marker cells; their colours will paint the mirrored shapes.")
    for wi, w in enumerate(walls):
        if wi not in assign:
            continue
        my, mx, mc = markers[assign[wi]]
        wx = w[0][1]
        wset = set(w)
        # flood 4-cells 8-connected starting from cells adjacent to the wall
        seen = set()
        stack = []
        for y, x in w:
            for dy in (-1, 0, 1):
                for dx in (-1, 1):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == 4 and (yy, xx) not in seen:
                        seen.add((yy, xx)); stack.append((yy, xx))
        while stack:
            y, x = stack.pop()
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == 4 and (yy, xx) not in seen:
                        seen.add((yy, xx)); stack.append((yy, xx))
        for y, x in seen:
            nx = 2 * wx - x
            if 0 <= nx < W and out[y, nx] == 0:
                out[y, nx] = mc
        emit(out.copy(), f"Mirror the 4-shape across the wall at x={wx} in colour {mc}.")
    emit(out.copy(), "Final grid.")
    return out
